                sub=tuple(i for i in ids if rows[i][2][t]==r)
                if sub:
                    value+=F(sum(rows[i][1] for i in sub),w)*solve(sub,tuple(x for x in available if x!=t),budget-1)[0]
            best=min(best,(value,tests[t]))
    return best
