from fractions import Fraction as F
# W=1 selects these rows; redisplaying the same stored value adds no evidence.
rows=[('A',3,{'T':0,'U':0,'V':0}),('B',5,{'T':0,'U':0,'V':1}),('D',5,{'T':0,'U':0,'V':1})]
modes='ABCD'
L={'A':[0,11,6,16],'B':[22,0,20,8],'C':[16,23,0,7],'D':[18,11,20,0]}
cost={'T':F('1.8'),'U':F('1.5'),'V':F('7.2')}
def repair(sub):
    w=sum(r[1] for r in sub)
    return min((F(sum(r[1]*L[a][modes.index(r[0])] for r in sub),w),a) for a in modes)
def evaluate():
    w=sum(r[1] for r in rows)
    posterior={m:float(F(sum(r[1] for r in rows if r[0]==m),w)) for m in modes}
    remaining={a:float(F(sum(r[1]*L[a][modes.index(r[0])] for r in rows),w)) for a in modes}
    for t in cost:
        val=cost[t]
        for outcome in (0,1):
            sub=[r for r in rows if r[2][t]==outcome]
            if sub:val+=F(sum(r[1] for r in sub),w)*repair(sub)[0]
        remaining[t]=float(val)
    action=min(remaining,key=remaining.get)
    after={}
    if action in cost:
        for outcome in (0,1):
            sub=[r for r in rows if r[2][action]==outcome]
            after[str(outcome)]=repair(sub)[1] if sub else 'IMPOSSIBLE'
    return {'posterior':posterior,'remaining_losses':remaining,'action':action,'repair_after':after}
result=evaluate()
# Independent hand-derived weighted sums and informative-test value.
expected={'A':F(135,13),'B':F(106,13),'C':F(198,13),'D':F(109,13),'T':F(106,13)+F(18,10),'U':F(106,13)+F(15,10),'V':F(72,10)+F(40,13)}
assert all(abs(result['remaining_losses'][k]-float(v))<1e-12 for k,v in expected.items())
assert result['action']=='B'
print(result)
print('Verified against independent weighted-loss calculations.')

